def migrate_legacy_work_items(apps, schema_editor):
    WorkOrder = apps.get_model("core", "PartnerWorkOrder")
    WorkOrderLine = apps.get_model("core", "PartnerWorkOrderLine")
    for work_order in WorkOrder.objects.all().iterator():
        if WorkOrderLine.objects.filter(work_order_id=work_order.pk).exists():
            continue
        legacy_items = work_order.items if isinstance(work_order.items, list) else []
        for index, item in enumerate(legacy_items):
            if not isinstance(item, dict):
                continue
            title = item.get("title") or item.get("name") or "정비 항목"
            amount = item.get("amount_krw", 0)
            if not isinstance(title, str) or type(amount) is not int or amount < 0:
                continue
            WorkOrderLine.objects.create(
                work_order_id=work_order.pk,
                kind="other",
                description=title[:160],
                quantity=1,
                unit="건",
                unit_price_krw=amount,
                sort_order=index,
            )


